170	fn the_final_countdown<'scope>(
171	    s: &Scope<'scope>,
172	    bottom_of_stack: &'scope i32,
173	    max: &'scope Mutex<usize>,
174	    n: usize,
175	) {
176	    let top_of_stack = 0;
177	    let p = bottom_of_stack as *const i32 as usize;
178	    let q = &top_of_stack as *const i32 as usize;
