     use rayon::scope;
     use std::sync::atomic::{AtomicUsize, Ordering};

     fn main() {
         let counter = AtomicUsize::new(0);
         let spawned = AtomicUsize::new(0);
         scope(|s| {
             for i in 0..100 {
                 let (counter, spawned) = (&counter, &spawned);
                 s.spawn(move |s1| {
                     counter.fetch_add(1, Ordering::SeqCst);
                     spawned.fetch_add(1, Ordering::SeqCst);
                     if i == 0 {
                         // 任务内再造任务：围栏必须连它一起等
                         let counter = &counter;
                         s1.spawn(move |_| counter.fetch_add(1000, Ordering::SeqCst));
                     }
                 });
             }
         });
         println!("total = {}", counter.load(Ordering::SeqCst));
     }
     ```

3. **需要观察的现象**：测试全绿；实验输出 `total = 1100`（99 个 +1、1 个 +1000 再加 1——即 100 个任务各 +1，其中第一个额外 +1000）。注意 `spawn` 在 for 循环里通过元组同时共享两个 `&AtomicUsize`，正是 4.1 借用规则的活用。

